               ADD A,C                         ; 426D 81
               RET                             ; 426E C9
               PUSH HL                         ; 426F E5
               LD BC,&FFAF                     ; 4270 01 AF FF
               ADD HL,BC                       ; 4273 09
               POP HL                          ; 4274 E1
               JR NC,L4279                     ; 4275 30 02
               INC HL                          ; 4277 23
               INC HL                          ; 4278 23

; ---- L4279 ---- from &4275
L4279:
               DEC HL                          ; 4279 2B
               LD BC,&0014                     ; 427A 01 14 00
               XOR A                           ; 427D AF
               DEC A                           ; 427E 3D

; ---- L427F ---- from &4282
L427F:
