               ADD A,A                         ; 4A70 87
               ADD A,C                         ; 4A71 81
               ADD A,A                         ; 4A72 87
               LD C,A                          ; 4A73 4F
               LD A,(DE)                       ; 4A74 1A
               INC DE                          ; 4A75 13
               INC DE                          ; 4A76 13
               SUB CH_ZERO                     ; 4A77 D6 30
               ADD A,C                         ; 4A79 81
               RET                             ; 4A7A C9

