               LD A,(SOFV+&4000)               ; 59E8 3A 02 80
               AND A                           ; 59EB A7
               JR Z,L59FC                      ; 59EC 28 0E
               LD HL,SOFCOUNT+&4000            ; 59EE 21 73 80
               DEC (HL)                        ; 59F1 35
               JR NZ,L59FC                     ; 59F2 20 08
               LD (HL),A                       ; 59F4 77
               LD HL,SOFFCT                    ; 59F5 21 C4 5A
               DEC (HL)                        ; 59F8 35
               JR NZ,L59FC                     ; 59F9 20 01
               INC (HL)                        ; 59FB 34

