               PUSH AF                         ; 5D37 F5
               LD BC,&0006                     ; 5D38 01 06 00
               LDIR                            ; 5D3B ED B0
               LD A,&F5                        ; 5D3D 3E F5
               LD (DE),A                       ; 5D3F 12
               INC DE                          ; 5D40 13
               LD C,&05                        ; 5D41 0E 05
               LDIR                            ; 5D43 ED B0
               PUSH HL                         ; 5D45 E5
               LD HL,L5DCA                     ; 5D46 21 CA 5D
               LD C,&07                        ; 5D49 0E 07
               LDIR                            ; 5D4B ED B0
               POP HL                          ; 5D4D E1
               LD C,&10                        ; 5D4E 0E 10
               LDIR                            ; 5D50 ED B0
               LD HL,L5DD1                     ; 5D52 21 D1 5D
               LD C,&4E                        ; 5D55 0E 4E

