               JR NZ,L5FDA                     ; 5FCE 20 0A
               LD HL,&5617                     ; 5FD0 21 17 56
               BIT 5,A                         ; 5FD3 CB 6F
               JR NZ,L5FDA                     ; 5FD5 20 03
