L64B9:
               EX AF,AF'                       ; 64B9 08
               PUSH HL                         ; 64BA E5
               LD E,&08                        ; 64BB 1E 08
               EXX                             ; 64BD D9
               LD A,(HL)                       ; 64BE 7E
               INC HL                          ; 64BF 23
               EXX                             ; 64C0 D9
               LD D,A                          ; 64C1 57
               LD A,&01                        ; 64C2 3E 01

; ---- L64C4 ---- from &64DB
L64C4:
               LD B,C                          ; 64C4 41

; ---- L64C5 ---- from &64D6
L64C5:
