               RLA                             ; 64C7 17
               JR NC,L64D4                     ; 64C8 30 0A
               LD (HL),A                       ; 64CA 77
               LD A,L                          ; 64CB 7D
               ADD A,&08                       ; 64CC C6 08
               LD L,A                          ; 64CE 6F
               JR NC,L64D2                     ; 64CF 30 01
               INC H                           ; 64D1 24

; ---- L64D2 ---- from &64CF
L64D2:
