               LD (DE),A                       ; 6503 12
               INC DE                          ; 6504 13
               LD A,E                          ; 6505 7B
               CP &90                          ; 6506 FE 90
               JR NZ,L6529                     ; 6508 20 1F
               PUSH HL                         ; 650A E5
               PUSH BC                         ; 650B C5
               EXX                             ; 650C D9
               PUSH BC                         ; 650D C5
               PUSH DE                         ; 650E D5
               LD HL,SCRNBUF                   ; 650F 21 88 51
               LD A,(DMPFG)                    ; 6512 3A B7 5A
               AND A                           ; 6515 A7

L6516:
               CALL Z,&0000                    ; 6516 CC 00 00  the operand is written here at run time, from &7637
               LD A,(DHADJ)                    ; 6519 3A 82 5B
               ADD A,&08                       ; 651C C6 08
               LD (DHADJ),A                    ; 651E 32 82 5B
               POP DE                          ; 6521 D1
