               LD HL,DEVICE                    ; 6B16 21 73 5A
               LD A,(HL)                       ; 6B19 7E
               LD (HL),&00                     ; 6B1A 36 00
               PUSH AF                         ; 6B1C F5
               PUSH HL                         ; 6B1D E5
               CALL JNCHAR                     ; 6B1E CD 84 01
               LD A,&20                        ; 6B21 3E 20
               JR C,L6B26                      ; 6B23 38 01
               LD A,(HL)                       ; 6B25 7E

; ---- L6B26 ---- from &6B23
L6B26:
