               LD A,E                          ; 6B2C 7B
               INC E                           ; 6B2D 1C
               CP C                            ; 6B2E B9
               JR NZ,L6B14                     ; 6B2F 20 E3
               LD A,&0D                        ; 6B31 3E 0D
               RST PRINT_A                     ; 6B33 D7
