               DEC HL                          ; 7A6C 2B
               LD E,(HL)                       ; 7A6D 5E
               EX DE,HL                        ; 7A6E EB
               LD (L7DC5+1),HL                 ; 7A6F 22 C6 7D  patches the operand of the CALL at &7DC5
               POP HL                          ; 7A72 E1
