               LD DE,PUTSWA                    ; 7B11 11 00 40  &4000 here is the window offset -- CHANS is a system variable in the page now at &8000 -- and not the XVAR that shares the address
               ADD HL,DE                       ; 7B14 19
               LD DE,L49F7                     ; 7B15 11 F7 49
               LD (HL),E                       ; 7B18 73
               INC HL                          ; 7B19 23
               LD (HL),D                       ; 7B1A 72
               INC HL                          ; 7B1B 23
               INC HL                          ; 7B1C 23
               INC HL                          ; 7B1D 23
               INC HL                          ; 7B1E 23
               LD (HL),E                       ; 7B1F 73
